// Protocol facts: Microsoft WmiMonitorBrightness/Methods/WmiSetBrightness docs.
// This file performs no WMI/native I/O; only the separate worker hosts WMI.
using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;

namespace RogControl {
 public static class WindowsBrightnessRules {
  public const int MaximumMonitors=16,LeaseMilliseconds=30000,WorkerBudgetMilliseconds=10000;
  public static bool Token(string value){return value!=null&&value.Length==32&&value.All(c=>c>='0'&&c<='9'||c>='a'&&c<='f');}
  public static bool HashToken(string value){return value!=null&&value.Length==64&&value.All(c=>c>='0'&&c<='9'||c>='a'&&c<='f');}
  public static bool TargetId(string value){return value!=null&&value.StartsWith("brightness-",StringComparison.Ordinal)&&HashToken(value.Substring(11));}
  public static bool UnknownMethodCompletion(string code){return code=="METHOD_EXCEPTION"||code=="INVALID_METHOD_RESULT";}
  public static bool LevelsValid(int[] levels,int? count,int? current){return levels!=null&&count.HasValue&&levels.Length==count.Value&&levels.Length>0&&levels.Length<=101&&levels.All(v=>v>=0&&v<=100)&&levels.Distinct().Count()==levels.Length&&current.HasValue&&levels.Contains(current.Value);}
  public static bool Current(DateTime captured,DateTime now){if(captured.Kind!=DateTimeKind.Utc||now.Kind!=DateTimeKind.Utc)return false;var age=now-captured;return age>=TimeSpan.Zero&&age<=TimeSpan.FromMilliseconds(LeaseMilliseconds);}
  internal static string Hash(string value){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-","").ToLowerInvariant();}
 }
 internal sealed class BrightnessRawMonitor {internal string InstanceName {get;set;}internal string FriendlyName {get;set;}internal bool? Active {get;set;}internal int? Current {get;set;}internal int? LevelCount {get;set;}internal int[] Levels {get;set;}}
 internal sealed class BrightnessRawMethod {internal string InstanceName {get;set;}internal bool? Active {get;set;}}
 internal interface IWindowsBrightnessNative {BrightnessRawMonitor[] ReadMonitors();BrightnessRawMethod[] ReadMethods();uint SetBrightness(string exactInstanceName,int value);}
 internal sealed class WindowsBrightnessProtocolError:Exception {internal readonly string Code;internal WindowsBrightnessProtocolError(string code):base(code){Code=code;}}
 internal sealed class WindowsBrightnessService {
  sealed class Prepared {internal string Id,Name,Instance,Fingerprint,Reason;internal int? Current;internal int[] Levels;internal bool Ready;}
  readonly IWindowsBrightnessNative api;readonly Func<long> clock;readonly Func<DateTime> utc;readonly string session,salt;Dictionary<string,Prepared> lease;string readToken;long captured;
  internal WindowsBrightnessService(IWindowsBrightnessNative native,Func<long> milliseconds,Func<DateTime> now){if(native==null||milliseconds==null||now==null)throw new ArgumentNullException();api=native;clock=milliseconds;utc=now;session=Guid.NewGuid().ToString("N");salt=Guid.NewGuid().ToString("N");}
  static object Value(IDictionary<string,object> map,string key){object value;return map!=null&&map.TryGetValue(key,out value)?value:null;}
  static string Text(IDictionary<string,object> map,string key){return Value(map,key) as string;}
  static bool InstanceValid(string value){return !String.IsNullOrWhiteSpace(value)&&value.Length<=512&&!value.Any(Char.IsControl);}
  internal static Dictionary<string,object> Object(params object[] values){var map=new Dictionary<string,object>();for(int i=0;i<values.Length;i+=2)map[(string)values[i]]=values[i+1];return map;}
  Prepared[] Query(){var rows=api.ReadMonitors();var methods=api.ReadMethods();if(rows==null||methods==null||rows.Length>WindowsBrightnessRules.MaximumMonitors||methods.Length>WindowsBrightnessRules.MaximumMonitors)throw new WindowsBrightnessProtocolError("INVALID_PROVIDER_DATA");var all=new List<Prepared>();foreach(var raw in rows.Where(r=>r!=null&&r.Active==true&&InstanceValid(r.InstanceName)).OrderBy(r=>r.InstanceName,StringComparer.Ordinal)){bool unique=rows.Count(r=>r!=null&&r.InstanceName==raw.InstanceName)==1;var paired=methods.Where(m=>m!=null&&m.InstanceName==raw.InstanceName).ToArray();bool pairing=paired.Length==1&&paired[0].Active==true;bool valid=unique&&WindowsBrightnessRules.LevelsValid(raw.Levels,raw.LevelCount,raw.Current);string reason=!unique?"AMBIGUOUS_MONITOR":!valid?"INVALID_LEVELS":!pairing?"METHOD_NOT_PAIRED":null;var levels=valid?raw.Levels.OrderBy(v=>v).ToArray():new int[0];var name=raw.FriendlyName;if(String.IsNullOrWhiteSpace(name)||name.Length>64||name.Any(c=>Char.IsControl(c)||Char.IsSurrogate(c)))name="屏幕 "+(all.Count+1);var prepared=new Prepared{Id="brightness-"+WindowsBrightnessRules.Hash(salt+"|"+raw.InstanceName),Name=name,Instance=raw.InstanceName,Current=valid?raw.Current:null,Levels=levels,Ready=reason==null,Reason=reason};prepared.Fingerprint=WindowsBrightnessRules.Hash(salt+"|"+raw.InstanceName+"|"+prepared.Current+"|"+String.Join(",",levels)+"|"+prepared.Ready);all.Add(prepared);}return all.GroupBy(r=>r.Id,StringComparer.Ordinal).Select(g=>g.First()).ToArray();}
  static Dictionary<string,object> Describe(Prepared row){return Object("id",row.Id,"name",row.Name,"currentBrightness",row.Current.HasValue?(object)row.Current.Value:null,"levels",row.Levels,"supportsWrite",row.Ready,"fingerprint",row.Fingerprint,"unavailableReason",row.Reason);}
  Dictionary<string,object> Snapshot(Prepared[] rows){return Object("schema",1,"sessionToken",session,"readToken",readToken,"capturedAtUtc",utc().ToUniversalTime().ToString("o"),"expiresAfterMilliseconds",WindowsBrightnessRules.LeaseMilliseconds,"monitors",rows.Select(Describe).ToArray());}
  internal Dictionary<string,object> Handle(Dictionary<string,object> request){if(request==null)throw new WindowsBrightnessProtocolError("INVALID_REQUEST");string op=Text(request,"op");if(op=="read"){if(request.Keys.Any(k=>k!="id"&&k!="op"))throw new WindowsBrightnessProtocolError("INVALID_REQUEST");lease=null;readToken=null;var rows=Query();captured=clock();if(captured<0)throw new WindowsBrightnessProtocolError("INVALID_CLOCK");readToken=Guid.NewGuid().ToString("N");lease=rows.GroupBy(r=>r.Id,StringComparer.Ordinal).Where(g=>g.Count()==1).ToDictionary(g=>g.Key,g=>g.First(),StringComparer.Ordinal);return Snapshot(rows);}if(op!="set")throw new WindowsBrightnessProtocolError("INVALID_REQUEST");
   string[] fields={"id","op","targetId","brightness","sessionToken","readToken","currentFingerprint","experimental"};object brightness=Value(request,"brightness");if(request.Keys.Any(k=>!fields.Contains(k))||!System.Object.Equals(Value(request,"experimental"),true)||!(brightness is int)||(int)brightness<0||(int)brightness>100||!WindowsBrightnessRules.TargetId(Text(request,"targetId"))||!WindowsBrightnessRules.Token(Text(request,"sessionToken"))||!WindowsBrightnessRules.Token(Text(request,"readToken"))||!WindowsBrightnessRules.HashToken(Text(request,"currentFingerprint")))throw new WindowsBrightnessProtocolError("INVALID_REQUEST");
   long now=clock();Prepared before;string id=Text(request,"targetId");if(lease==null||readToken==null||now<captured||now-captured>WindowsBrightnessRules.LeaseMilliseconds||Text(request,"sessionToken")!=session||Text(request,"readToken")!=readToken||!lease.TryGetValue(id,out before)||Text(request,"currentFingerprint")!=before.Fingerprint)throw new WindowsBrightnessProtocolError("CAPTURE_EXPIRED");if(!before.Ready||!before.Levels.Contains((int)brightness))throw new WindowsBrightnessProtocolError("UNSUPPORTED_LEVEL");
   var fresh=Query().Where(r=>r.Id==id).ToArray();if(fresh.Length!=1||!fresh[0].Ready||fresh[0].Instance!=before.Instance||fresh[0].Fingerprint!=before.Fingerprint)throw new WindowsBrightnessProtocolError("CURRENT_CHANGED");now=clock();if(now<captured||now-captured>WindowsBrightnessRules.LeaseMilliseconds)throw new WindowsBrightnessProtocolError("CAPTURE_EXPIRED");before=fresh[0];lease=null;readToken=null;
   if(before.Current==(int)brightness)return Object("schema",1,"alreadyCurrent",true,"writeAttempted",false,"methodReturnCode",null,"readbackConfirmed",true,"errorCode",null,"observed",Describe(before),"originalBrightness",before.Current);
   uint? code=null;string error=null;try{code=api.SetBrightness(before.Instance,(int)brightness);if(code!=0)error="METHOD_FAILED";}catch(WindowsBrightnessProtocolError failure){error=failure.Code=="INVALID_METHOD_RESULT"?"INVALID_METHOD_RESULT":"METHOD_EXCEPTION";}catch(Exception){error="METHOD_EXCEPTION";}
   Prepared observed=null;try{var after=Query().Where(r=>r.Id==id).ToArray();if(after.Length==1&&after[0].Ready&&after[0].Instance==before.Instance&&after[0].Levels.SequenceEqual(before.Levels))observed=after[0];else if(error==null)error="READBACK_IDENTITY_CHANGED";}catch(Exception){if(error==null)error="READBACK_FAILED";}
   bool confirmed=code==0&&observed!=null&&observed.Current==(int)brightness;if(!confirmed&&error==null)error="READBACK_MISMATCH";return Object("schema",1,"alreadyCurrent",false,"writeAttempted",true,"methodReturnCode",code.HasValue?(object)code.Value:null,"readbackConfirmed",confirmed,"errorCode",error,"observed",observed==null?null:Describe(observed),"originalBrightness",before.Current);
  }
 }
}
